  ('13e9caed-5185-59cd-a164-cd1d1836c222', '5df117af-d5e0-5b71-8caa-6806c47bdff1', 9, 'Checkpoint 9', 'checkpoint', 'draft'),
  ('795b0fde-531f-5577-85b4-4c997321523c', 'cc27542c-c983-52aa-88c4-8fe075eb0a0f', 4, 'At the café', 'story', 'published')
insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('18ab5904-7009-5924-be6f-98b6d24ecd73', '7acbb453-0fe4-550b-87a1-c81f0f7e4bd3', 'Un café, por favor', 'The shortest way to order anything: name it and add **por favor**. *Un café, por favor.* *Una medialuna, por favor.* No verb needed.', 'published'),
  ('7d00df14-5cdf-59b1-9f3d-dc74b8626908', '7acbb453-0fe4-550b-87a1-c81f0f7e4bd3', 'Facturas', '**Facturas** are the pastries you buy by the dozen at the bakery — *medialunas* are the best known. Nothing to do with bills.', 'published'),
  ('8b938cde-ecea-5e1b-bd22-3219656dc110', 'cc27542c-c983-52aa-88c4-8fe075eb0a0f', 'Che', '**Che** is how people in Buenos Aires get someone''s attention — like "hey" or "mate". It''s friendly, never rude.', 'published'),
  ('03c07d66-92a9-54f3-842f-c123a1a62c76', 'cc27542c-c983-52aa-88c4-8fe075eb0a0f', 'Soy', 'To say who you are, use **soy**: *Soy Sofi.* One word carries "I am" — Spanish has no separate word for "I" here.', 'published'),
  ('d6547b7a-4812-57d4-9cbd-00e7db9fd94f', 'aea4c640-a7bd-5aba-8ce2-5c2f493637a3', 'Vos, not tú', 'In Argentina the everyday word for "you" is **vos**, and it has its own verb forms: *vos sos* (you are). You''ll hear *tú* in other countries. This course never uses it.', 'draft'),
  ('48324a75-b349-562d-93c8-7f6374678d29', 'd35a777a-0a33-5ede-8fb9-39d0107d41f6', 'Me llamo, te llamás', 'Spanish says you *call yourself*: **me llamo Sofi** — my name is Sofi. Asking someone else: **¿cómo te llamás?**', 'draft'),
  ('d7750d49-3d52-53be-8430-e5de05c8a3bc', '7c5e7c59-5c44-52e3-9900-449c03934359', 'Ser de', 'To say where someone is from, put **de** after the verb: *Soy de Rosario.* *¿De dónde sos?*', 'draft'),
  ('83c8a556-cf91-503a-a643-c7ce326fcbab', '481ae401-6c6e-53d7-9683-853d0cbed672', 'Es', 'One form covers both: **él es** and **ella es**. It also works for a name: *Juan es de Rosario.*', 'draft'),
  ('2716df1c-2df3-5169-b0dc-9fd53d8444b4', '481ae401-6c6e-53d7-9683-853d0cbed672', 'You can drop the pronoun', 'The verb already says who: *soy* is only ever "I am", *sos* only "you are". So **Soy de acá** and *Yo soy de acá* are both right, and the short one is what people say.', 'draft'),
  ('f62f34aa-e166-53b8-a8ce-cb48487e0e8c', '70dda450-3825-5ea7-88fd-296775bc426c', 'Argentino or argentina', 'These words change with the person: **argentino** for a man, **argentina** for a woman. Same for *uruguayo / uruguaya*, *chileno / chilena*.', 'draft'),
  ('5ee9b5a6-665f-5a3d-95f7-59b3e29898c9', '70dda450-3825-5ea7-88fd-296775bc426c', 'Porteño', 'Someone from the city of Buenos Aires is **porteño** or **porteña** — from *puerto*, the port. People from the rest of the country are not.', 'draft'),
  ('f99e22db-f796-5bbb-a161-afec37a68bc3', '9a649d54-c14a-56da-8701-c4783ad9a159', 'Words are masculine or feminine', 'A word ending in **-o** is usually masculine and takes *un*: *un hermano*. One ending in **-a** is usually feminine and takes *una*: *una hermana*.', 'draft'),
  ('f64b190f-60eb-5b5b-8017-03d0b27f48d1', '9a649d54-c14a-56da-8701-c4783ad9a159', 'Mis viejos', '**Mi viejo** and **mi vieja** — literally "my old one" — are affectionate Argentine words for *my dad* and *my mum*.', 'draft'),
  ('273647e4-003f-5e11-a1ef-b6c77da3280a', 'b28a06e8-ef82-54f0-bbf4-5314e84a7ece', 'You have your age', 'Spanish says you *have* years: **Tengo veinte años** — I''m twenty. *Tenés* is the vos form, *tiene* is for him or her.', 'draft'),
  ('82c92152-1296-5058-b7e1-6deb2183513e', 'f1fa7454-72a3-546d-8f72-4aab149bbbbe', 'More than one', 'Add **-s** after a vowel (*medialuna → medialunas*) and **-es** after a consonant. The word for "a" disappears: *una empanada*, but *dos empanadas*.', 'draft'),
  ('81f0edea-517c-5fc8-a10c-abf8f72ba4fa', 'f1fa7454-72a3-546d-8f72-4aab149bbbbe', 'El kiosco', 'A **kiosco** is the corner shop that sells drinks, sweets and bus cards, often through a window onto the street. Many never close.', 'draft'),
  ('040623f8-7ca5-5206-8e5c-f178b0d6fbe4', '3cc8b1a1-6314-5a4f-be82-b713ea584203', 'Ustedes', 'For more than one person, Argentina uses **ustedes** with the same verb form as *ellos*: *ustedes son*, *ellos son*.', 'draft'),
  ('ac35e5d9-477d-5c6b-8ab2-e9b20516f7f6', '71481540-7f7c-5939-9d96-ee76d80128b9', 'Estar for where things are', 'Use **estar** for where someone or something is: *¿Dónde estás?* *El kiosco está acá.* It is a different verb from *ser*, which says what something is.', 'draft'),
  ('e70098bf-8ca4-58e1-95ea-97fbd9aba81f', '71481540-7f7c-5939-9d96-ee76d80128b9', 'El, la, los, las', 'The word for "the" matches its noun: **el** kiosco, **la** esquina, **los** kioscos, **las** esquinas.', 'draft'),
  ('a428b131-df79-589d-a5f0-80eaf97eb38f', 'e4dc651e-4fd9-5ba8-8e83-1c8a4131e09e', 'Hay or está', '**Hay** introduces something: *Hay un kiosco* — there''s a kiosco. **Está** says where something you already know about is: *El kiosco está en la esquina.*', 'draft'),
  ('023d7655-6ede-5117-a717-f98e585b037c', 'e4dc651e-4fd9-5ba8-8e83-1c8a4131e09e', 'Del and al', '*de + el* always becomes **del**, and *a + el* becomes **al**: *la parada del bondi*, *voy al centro*.', 'draft'),
  ('1de88b30-f9bf-5d0a-bcf4-7480ca1d4cc7', 'e4dc651e-4fd9-5ba8-8e83-1c8a4131e09e', 'El bondi', '**Bondi** is the everyday word for the city bus; *colectivo* is the neutral one. The **subte** is the Buenos Aires underground.', 'draft'),
  ('23158cf0-d54a-5955-b50d-bd27fbb6c514', 'eda0d38b-9df5-5bba-9665-c300309be0fa', 'Estar for how you feel', 'Use **estar** for how you are right now: *estoy cansado*, *¿estás nerviosa?* The adjective matches the person: *cansado* for a man, *cansada* for a woman.', 'draft'),
  ('bdbf4ab9-d5f6-592a-8ac8-00a6005e0f02', 'eda0d38b-9df5-5bba-9665-c300309be0fa', 'Medio', '**Medio** in front of an adjective softens it — *estoy medio cansado*, I''m kind of tired. It never changes: *medio cansada* too.', 'draft'),
  ('9b8de7a7-8ce6-5500-a8ab-a7d35c9c940e', 'c5c43fc3-949b-5f6c-99b4-c6da645e7d7f', '-ar verbs with vos', 'Regular **-ar** verbs: *laburo, laburás, labura, laburamos, laburan*. The vos form stresses the last syllable and carries an accent: *hablás*, *estudiás*.', 'draft'),
  ('f037e9d0-eab0-5582-a090-a30cc0c7bd0f', 'c5c43fc3-949b-5f6c-99b4-c6da645e7d7f', 'Laburar', '**Laburar** is the everyday Argentine word for *to work* — from the Italian *lavorare*. *Trabajar* is understood everywhere and fine too.', 'draft'),
  ('dee7197c-bac0-54b1-aad6-dd4fd838f50a', 'b95d926c-3168-53bd-88bd-c02c868d1119', 'Gustar works backwards', '**Me gusta el mate** means "mate pleases me". The verb matches the thing you like: *me gusta el café*, but *me gustan las facturas*.', 'draft'),
  ('6c6949b3-904f-59fe-8a19-085c5f916515', 'a2eec2e1-5a4c-5372-a1e8-7ac3076576e6', '¿Me traés…?', 'The easy way to order is to ask the waiter to bring it: **¿Me traés un café?** — literally "do you bring me a coffee?". *Quiero un café* works too. Add **por favor**.', 'draft'),
  ('5accb3e5-9f5d-571b-b159-856ad4feb161', 'a2eec2e1-5a4c-5372-a1e8-7ac3076576e6', 'El mozo', 'In Argentina the waiter is **el mozo** (or *la moza*). When you''re done, ask for **la cuenta**. A **cortado** is an espresso with a dash of milk.', 'draft'),
  ('d562d75d-012b-5f9d-95e6-ea87c0d54197', '6f572b83-5cbe-528d-bcdf-bbfc32e2b19c', 'Tener que', '**Tener que** + infinitive says what you have to do: *Tengo que laburar*, *¿tenés que estudiar?*', 'draft'),
  ('2375ef12-8a94-5b13-ba9c-dfbfe8356608', '6f572b83-5cbe-528d-bcdf-bbfc32e2b19c', 'Facu, and jobs without "a"', '**Facu** is short for *facultad* — university. For jobs, Spanish drops the article: **Soy profesora**, not *soy una profesora*.', 'draft'),
  ('64263c49-9bbb-598d-b1cd-cbef6fb9640b', '1974689a-177e-55c9-b4b1-69fba40389f0', '-er and -ir verbs with vos', 'Vos keeps the vowel of the infinitive and stresses it: *comer* → **comés**, *vivir* → **vivís**, *leer* → **leés**.', 'draft'),
  ('f9a1e455-91a4-5b1f-89f4-59d39156345f', 'c7cbf578-23ab-5875-9a1c-8104be80ad3e', 'Depto, pieza, living', 'Argentines say **depto** for an apartment, **pieza** for a bedroom and **el living** for the living room. The fridge is **la heladera**.', 'draft'),
  ('1e446ee3-53a4-5181-a51e-2885d09b86c2', 'c7cbf578-23ab-5875-9a1c-8104be80ad3e', 'Dos ambientes', 'Flats are sized in **ambientes** — rooms, not counting the kitchen and bathroom. *Un dos ambientes* has a living room and one bedroom.', 'draft'),
  ('97b6abce-e595-58cb-a895-30319da57ada', '61a56ded-546a-5ad6-a8ac-310375bed4ac', 'Telling the time', '*Es la una* (one o''clock), but *son las dos*, *son las siete*. Add **y media** for half past and **y cuarto** for quarter past. *A la noche* means at night.', 'draft'),
  ('e9b5fcfc-ba53-5a53-b7c5-cfbebadbf0e4', 'be613042-6935-5185-bf3a-fa4dc33eca15', 'Where things are', '**al lado de** (next to), **enfrente de** (across from), **entre** (between). Remember *de + el* = *del*: *al lado del kiosco*.', 'draft'),
  ('60a0e23a-105b-5cb4-9050-8c72b6869833', '740b6205-cb92-54dc-806f-96cc347f8ee0', 'No stem change with vos', '*Querer* and *poder* change their stem in most forms (*quiero*, *puede*) — but not with vos: **querés**, **podés**. *Ir* is fully irregular: *voy, vas, va, vamos, van*.', 'draft'),
  ('d9d31823-d8d6-55a0-8dec-8d39548ee263', '3376ea65-8afe-56be-bae8-b5d06b46c9cd', 'Vos commands', 'Drop the final *-r* and stress the last vowel: *mirar* → **mirá**, *venir* → **vení**. Pronouns stick to the end: **sentate**, **decime**, **esperame**.', 'draft'),
  ('14ab3922-a0da-5828-9009-788ce80ae5c3', '13fec277-30b8-5bdb-9718-e682351abfd9', 'Agreement, and re', 'Adjectives match their noun: *remera linda*, *zapatillas lindas*. **Re** in front of an adjective means *really*: *re lindo*. And **chico** means *small*.', 'draft'),
  ('fe95866f-3747-5f76-84e6-70b1453b221c', 'd8cb78a0-5a7d-5c09-9f7f-9e905e0d2e59', '¿Cuánto sale?', '**¿Cuánto sale?** is the everyday Argentine way to ask a price — *¿cuánto cuesta?* works too. **Mangos** is slang for pesos.', 'draft'),
  ('178244a5-d8b8-5e7d-a608-d9d95498e537', '441e2e5b-f704-511a-9e55-ef9613425ce8', 'Reflexive verbs', '*Me levanto, te levantás, se levanta* — the pronoun comes before the verb and matches the person. **Los sábados** means *on Saturdays*.', 'draft'),
  ('c95952cc-4578-5bd2-a762-e45f3792a19a', '2d151075-cd8d-51b2-9e1c-bf5a34e4ef1b', 'Also and neither', 'Agreeing with something positive: **A mí también.** Agreeing with something negative: **A mí tampoco.**', 'draft'),
  ('d48b1ff9-881c-5010-bbf2-fd3a16bc7729', '2c5ceb94-a924-5797-9279-29476c698177', 'Weather with hacer', '**Hace calor**, **hace frío** — it''s hot, it''s cold. Seasons are flipped: *el verano* runs from December to February.', 'draft'),
  ('d5a4acc0-9d64-5970-8f68-5d4ed9936d96', '5df117af-d5e0-5b71-8caa-6806c47bdff1', 'Right now', '**Estoy laburando** — I''m working (right now). In Argentina, *estoy llegando* can mean you''re still ten minutes away.', 'draft'),
  ('54719e83-d9d7-5d73-98e3-8ba760627cc8', '5df117af-d5e0-5b71-8caa-6806c47bdff1', 'Going to', '**Ir a** + infinitive talks about plans: *Vamos a hacer un asado.* **La semana que viene** is *next week*.', 'draft'),
  ('01e1a3a8-575e-5121-9fc4-7dd8f47262c1', '5df117af-d5e0-5b71-8caa-6806c47bdff1', 'Boludo and quilombo', '**Boludo** is common between close friends and an insult to anyone else — understand it, don''t use it yet. **Quilombo** means a mess; it''s informal, not rude, but keep it out of formal settings.', 'draft')
