-- ---------------------------------------------------------------------------
-- Seed: the course outline — generated by scripts/course/build-seed.mjs from
-- docs/course/section-*.yaml and scripts/course/fixtures/demo.yaml.
-- Do not edit by hand; regenerate.
--
-- The first 2 units of the course are published: they have lessons written.
-- Their sentences are hand-written and NOT yet reviewed by a native speaker.
-- The rest (28 units) go in as drafts — outline, words and tips — for the
-- pipeline to fill.
--
-- Idempotent: every row is an upsert on its deterministic id. Content that the
-- outline no longer has is retired at the end, never deleted: a learner's
-- progress points at it.
-- ---------------------------------------------------------------------------

-- Units are unique by (section, ordinal) and by course_order, so a unit that
-- moves would collide with whatever now sits in its place. Park both numbers
-- first; the upsert below sets every one back.
update public.units set ordinal = ordinal + 1000, course_order = course_order + 1000;
-- Lessons likewise: a story slotted in before a unit's check moves the check
-- down a place, into the ordinal the story is about to take. They are parked
-- below zero; whatever the upsert doesn't bring back is renumbered at the end.
update public.lessons set ordinal = -ordinal where ordinal > 0;

on conflict (id) do update set ordinal = excluded.ordinal, slug = excluded.slug, title_en = excluded.title_en, cefr = excluded.cefr, status = excluded.status;

on conflict (id) do update set section_id = excluded.section_id, ordinal = excluded.ordinal, course_order = excluded.course_order, slug = excluded.slug, title_en = excluded.title_en, summary_en = excluded.summary_en, grammar_focus = excluded.grammar_focus, register_max = excluded.register_max, status = excluded.status;

on conflict (id) do update set unit_id = excluded.unit_id, ordinal = excluded.ordinal, title_en = excluded.title_en, kind = excluded.kind, status = excluded.status;

on conflict (id) do update set unit_id = excluded.unit_id, title_en = excluded.title_en, body_md = excluded.body_md, status = excluded.status;

on conflict (id) do update set lemma = excluded.lemma, pos = excluded.pos, gloss_en = excluded.gloss_en, gloss_note_en = excluded.gloss_note_en, register = excluded.register, is_glue = excluded.is_glue, notes_en = excluded.notes_en, status = excluded.status;

on conflict (id) do update set lemma_id = excluded.lemma_id, form = excluded.form, features = excluded.features, gloss_en = excluded.gloss_en, gloss_note_en = excluded.gloss_note_en, unit_id = excluded.unit_id, audio_path = excluded.audio_path, status = excluded.status;

on conflict (id) do update set unit_id = excluded.unit_id, es = excluded.es, en = excluded.en, en_alt = excluded.en_alt, es_alt = excluded.es_alt, tokens = excluded.tokens, target_form_id = excluded.target_form_id, kind = excluded.kind, difficulty = excluded.difficulty, source = excluded.source, attribution = excluded.attribution, audio_path = excluded.audio_path, status = excluded.status;

delete from public.lesson_slots where lesson_id in ('bd4dc4d0-35c5-5619-9cd0-94fe274c2c1a', 'dbc87a42-a489-5610-85bc-ae962e85d575', '0bb58808-6701-5a0d-a899-a3a1599ecd32', 'c44368ae-3d6e-5b1a-a42d-42d84dc51931', '2d6ed2d4-bf6f-5456-a44f-5ca290967253', 'abeae42f-06c4-5523-b8e0-1c90c3c84654', '24af986b-0337-576a-8bb3-c2a1fe5aa3e2');

on conflict (id) do update set lesson_id = excluded.lesson_id, ordinal = excluded.ordinal, kind = excluded.kind, form_id = excluded.form_id, sentence_id = excluded.sentence_id, tip_id = excluded.tip_id, mode = excluded.mode, review_count = excluded.review_count, scope = excluded.scope;

delete from public.story_lines where lesson_id in ('795b0fde-531f-5577-85b4-4c997321523c');

on conflict (id) do update set lesson_id = excluded.lesson_id, ordinal = excluded.ordinal, speaker = excluded.speaker, sentence_id = excluded.sentence_id, question = excluded.question;

delete from public.unit_phrases where unit_id in ('7acbb453-0fe4-550b-87a1-c81f0f7e4bd3', 'cc27542c-c983-52aa-88c4-8fe075eb0a0f');

on conflict (unit_id, ordinal) do update set sentence_id = excluded.sentence_id;

