update public.sentences x set status = 'retired'
where x.status <> 'retired' and (
  -- its unit is gone
  (select u.status from public.units u where u.id = x.unit_id) = 'retired'
  -- it is live while its unit is not
  or (x.status = 'published' and (select u.status from public.units u where u.id = x.unit_id) <> 'published')
  -- re-slicing moved one of its words to a later unit than its own
  or exists (
    select 1
    from public.sentence_forms sf
    join public.forms f on f.id = sf.form_id
    join public.units fu on fu.id = f.unit_id
    join public.units xu on xu.id = x.unit_id
    where sf.sentence_id = x.id and fu.course_order > xu.course_order
  )
  -- another sentence written here already accepts it as an answer
  or exists (
    select 1 from public.sentences y
    where y.id <> x.id and y.id in ('4a3f9040-54f6-5480-b4d6-8fb3c1a01958', '0e567778-2c0e-5982-a4e4-1a15168170f8', '7eaca11b-3ca1-5dce-bbea-c3b90825dc99', 'cce5a9c3-893f-5bc9-9e45-5fbfcc3dea72', '61851b7c-842e-53dd-8381-611648d3a8e2', '8bf5a3ec-58e1-5812-b25c-abc88ca2fcf6', '65f0c0c8-b787-5abe-84f4-d7a2824bd0d9', 'd32c47c0-4b3f-53d1-ae34-6208e2328360', 'e29ca65d-44e5-5f3a-a227-eb979beefc08', '9658ab2d-c22c-57cd-be2c-a8c3e5e7aef0', '18305ab2-cc06-5021-9a3a-e36ec73128c5', 'caad848f-8898-509c-aeb0-983da017173c', '33c065a1-982a-5d5d-8f09-ab0132e85cea', '73f50b68-3420-55f1-9b74-fd065cfd3f1f', 'cb631b53-b406-564e-8043-846a65e211a4', '1200d3ac-b8e0-57f1-b522-e34ab06a3703', '28f9f0e1-99db-5d49-93ad-f165d9b6a56c', '9f6c924d-0a4e-5329-923c-69d11fc1b5f4', '9cb199b6-96fa-5c86-8a5f-94a0d61b3d36', 'c61fdedd-3e12-5770-a2d6-3168f752dbe3', 'b65498d1-369d-5baa-b6be-70c018304d80', '89fc950e-cc5e-5d26-905b-b2358f5db1da', 'da58266e-6714-5777-9a62-32a024ad3739', '82aae391-c42e-5040-986f-698c6261d414', 'd49a0542-5858-5645-b250-79e5e9130d98', '876908ac-68f3-5c35-a71a-f07d5aca0f87', 'be45b7fe-3a53-5445-932b-d237855acd67', '0c6e3148-d3fe-541b-9a21-517bfd8b7412', 'fbb8cc42-e32f-5587-b826-a38993545087', '3e21464d-fdbf-5521-9886-581c8cb336c2', 'a9c3cb1f-b601-5f47-8b9f-70d603afb8e7', '46cabb7e-ce14-58f5-8051-8fff7ab05c76', 'dceaca61-60b4-5bec-8d6c-3b213260d739', 'ed0f87aa-2319-5eb0-ab49-0e293d44ecfa', 'dbb2097d-75a4-5950-9f54-cd8365fd1d95', '7fffc189-8cc8-5e94-8e20-164fe102a505', 'b9f297da-4c6b-5b25-9f8d-755f5a5f8f5e', '5f874aad-e37f-582c-bda1-1fe6ceaace21', 'a25a4d70-dcb3-5613-8331-7675efd12000', '2b4cb00e-91f2-5e77-a5da-5fc72fe819a7', '2170e308-edf7-52a4-9a35-a2a1f2b7a54e', '7678a167-fa6b-5939-993c-0c839c7d5321', '56148f3a-9f02-5fb6-9f08-40dcdfcf8530') and x.es = any(y.es_alt)
